DenonAVRBridge.prototype._discover_mdns = function () {
    // ...
    browser.on('serviceUp', function (service) {
        if (service.port !== 80) {
            return;
        } else if (!service.addresses) {
            return;
        } else if (service.addresses.length === 0) {
